(280448, 19358, 6855, '<td valign="top">This is so gorgeous!  I will definitely be keeping it as a favorite when the contest is over!  Beautiful all the way around. 10 from me.</td>', 'This is so gorgeous!  I will definitely be keeping it as a favorite when the contest is over!  Beautiful all the way around. 10 from me.', '2003-04-28 02:21:55.000000', NULL, 1),
(280451, 19708, 6855, '<td valign="top">Very sweet - gret flow!  I don''t like the border color, but that is a very small nitpick.  All in all, I think this is gorgeous.</td>', 'Very sweet - gret flow!  I don''t like the border color, but that is a very small nitpick.  All in all, I think this is gorgeous.', '2003-04-28 02:24:21.000000', NULL, 1),
