(280453, 19620, 51167, '<td valign="top">wow, these photo''s are exceptional quality. The background colors and everything fit perfectly with the theme.  Great job.</td>', 'wow, these photo''s are exceptional quality. The background colors and everything fit perfectly with the theme.  Great job.', '2003-04-28 02:25:41.000000', NULL, 1),
(280454, 19688, 6855, '<td valign="top">And the winner is......the composition here is awesome - very creative - I wouldn''t mind having this hanging in my kitchen!  Awesome job!</td>', 'And the winner is......the composition here is awesome - very creative - I wouldn''t mind having this hanging in my kitchen!  Awesome job!', '2003-04-28 02:25:49.000000', NULL, 1),
