(280458, 19415, 6892, '<td valign="top">Like taking a moment to meditate and forget the cares of the noisy world we have created. Thank you.</td>', 'Like taking a moment to meditate and forget the cares of the noisy world we have created. Thank you.', '2003-04-28 02:31:35.000000', NULL, 1),
(280461, 19221, 6892, '<td valign="top">I''m remembering something Carl Sagan said about the creation of the universe, how bits of matter set out like the seeds of a dandelion...</td>', 'I''m remembering something Carl Sagan said about the creation of the universe, how bits of matter set out like the seeds of a dandelion...', '2003-04-28 02:34:29.000000', NULL, 1),
