(280467, 19716, 2923, '<td valign="top">Very nice! 10</td>', 'Very nice! 10', '2003-04-28 02:40:44.000000', NULL, 1),
(280468, 19280, 6892, '<td valign="top">You''ve portrayed well three of the many attitudes cats share. Being raised with these finicky creatures, you surely never know what to expect next. But we do love our kitties, don''t we? Love the tone used.</td>', 'You''ve portrayed well three of the many attitudes cats share. Being raised with these finicky creatures, you surely never know what to expect next. But we do love our kitties, don''t we? Love the tone used.', '2003-04-28 02:41:24.000000', NULL, 1),
(280470, 19641, 6892, '<td valign="top">e.g. Botanical life-cycle of a lovely lilly. Laud your choice of background color.</td>', 'e.g. Botanical life-cycle of a lovely lilly. Laud your choice of background color.', '2003-04-28 02:43:41.000000', NULL, 1),
(280471, 19514, 4210, '<td valign="top">I like the first and the last imagine. The center one lacks interest however.</td>', 'I like the first and the last imagine. The center one lacks interest however.', '2003-04-28 02:45:30.000000', NULL, 1),
