INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(280989, 19550, 6870, '<td valign="top">I like the misty look here, and the three panels show more than one photo could. Nice work! Lovely colors and tones and superb composition. 10</td>', 'I like the misty look here, and the three panels show more than one photo could. Nice work! Lovely colors and tones and superb composition. 10', '2003-04-28 13:44:42.000000', NULL, 1),
(280995, 19250, 6870, '<td valign="top">Really uniqe arrangement of these photos. This would be superb in a large, poster format.</td>', 'Really uniqe arrangement of these photos. This would be superb in a large, poster format.', '2003-04-28 13:52:35.000000', NULL, 1),
(280997, 19583, 6870, '<td valign="top">I don''t drink, but you do make this beer look attractive. I like  your seamless edges.</td>', 'I don''t drink, but you do make this beer look attractive. I like  your seamless edges.', '2003-04-28 13:53:10.000000', NULL, 1),
(280999, 19643, 6870, '<td valign="top">I''m not sure four picts are allowed, but i don''t care. This is nice stuff. The two train panels are so similar, though that it may be better to leave out the first, keep the second and rearrange the resulting images.</td>', 'I''m not sure four picts are allowed, but i don''t care. This is nice stuff. The two train panels are so similar, though that it may be better to leave out the first, keep the second and rearrange the resulting images.', '2003-04-28 13:54:28.000000', NULL, 1),
(281000, 19769, 6870, '<td valign="top">He looks disconnected, too. Very fun work. It gives kind of a postmodern feel to human anatomy.</td>', 'He looks disconnected, too. Very fun work. It gives kind of a postmodern feel to human anatomy.', '2003-04-28 13:55:10.000000', NULL, 1),
(281001, 19276, 1379, '<td valign="top">Nice little story!</td>', 'Nice little story!', '2003-04-28 13:55:34.000000', NULL, 1),
(281003, 19613, 6870, '<td valign="top">I wish these skeletons could be in a larger format so I could see them clearly. Really fun idea, giving the skeleton the symbolic appearance of longer length.</td>', 'I wish these skeletons could be in a larger format so I could see them clearly. Really fun idea, giving the skeleton the symbolic appearance of longer length.', '2003-04-28 13:56:12.000000', NULL, 1),
(281004, 19188, 1379, '<td valign="top">What a sweetie!  It''s great that you avoided getting any red-eye.</td>', 'What a sweetie!  It''s great that you avoided getting any red-eye.', '2003-04-28 13:56:48.000000', NULL, 1),
(281005, 19763, 3294, '<td valign="top">I like the idea here... although I feel it would be better balanced if the third photo was taken a little further away.  Like the first photo is a 3/4 view of the car, the second was a profile, and the third the back 3/4 view.  If that makes sense.  Best of luck!</td>', 'I like the idea here... although I feel it would be better balanced if the third photo was taken a little further away.  Like the first photo is a 3/4 view of the car, the second was a profile, and the third the back 3/4 view.  If that makes sense.  Best of luck!', '2003-04-28 13:57:42.000000', NULL, 1),
(281006, 19726, 6870, '<td valign="top">I like the sense of action and motion here. The three images provide different views of "black magic" and the emotions that go with. This is really quality photography in my view. 9</td>', 'I like the sense of action and motion here. The three images provide different views of "black magic" and the emotions that go with. This is really quality photography in my view. 9', '2003-04-28 13:57:51.000000', NULL, 1),
(281007, 19579, 1717, '<td valign="top">great photo!  very clever and very well executed.  good job!  10 from me.</td>', 'great photo!  very clever and very well executed.  good job!  10 from me.', '2003-04-28 13:58:09.000000', NULL, 1),
(281010, 19501, 1280, '<td valign="top">Great subject, a little dark though.</td>', 'Great subject, a little dark though.', '2003-04-28 14:00:35.000000', NULL, 1),
(281011, 19448, 3294, '<td valign="top">Nice submission!  I like the candidness.  And I love the dogs smile at the end there... great stuff.  Although I think the red shadows behind the photos are a bit distracting.</td>', 'Nice submission!  I like the candidness.  And I love the dogs smile at the end there... great stuff.  Although I think the red shadows behind the photos are a bit distracting.', '2003-04-28 14:00:40.000000', NULL, 1),
(281012, 19546, 1717, '<td valign="top">very well done and a great concept!  the lighting is wonderful.  good job!</td>', 'very well done and a great concept!  the lighting is wonderful.  good job!', '2003-04-28 14:01:19.000000', NULL, 1),
(281013, 19760, 1379, '<td valign="top">Lovely images, especially with that regal, cloudy sky in the background.  Your choice of font and color for the script really adds a delicate air to this.</td>', 'Lovely images, especially with that regal, cloudy sky in the background.  Your choice of font and color for the script really adds a delicate air to this.', '2003-04-28 14:01:20.000000', NULL, 1),
(281015, 19641, 1379, '<td valign="top">The photos are lovely, but somehow that plain white background detracts from the overall grace of your images.</td>', 'The photos are lovely, but somehow that plain white background detracts from the overall grace of your images.', '2003-04-28 14:03:10.000000', NULL, 1),
(281016, 19695, 1717, '<td valign="top">very well done.  good lighting and concept.  nice work!</td>', 'very well done.  good lighting and concept.  nice work!', '2003-04-28 14:03:32.000000', NULL, 1),
(281017, 19250, 3294, '<td valign="top">Interesting composition.  Looks like they were taken at different times of the day.</td>', 'Interesting composition.  Looks like they were taken at different times of the day.', '2003-04-28 14:03:43.000000', NULL, 1),
(281018, 19728, 1379, '<td valign="top">Very sweet!  I like the rhythmic, repeated background for each of these children.</td>', 'Very sweet!  I like the rhythmic, repeated background for each of these children.', '2003-04-28 14:03:55.000000', NULL, 1),
(281020, 19712, 3294, '<td valign="top">Appears to be the same photo, just seperated.  Not sure if it''s really a multi-image.  Nice photo though.</td>', 'Appears to be the same photo, just seperated.  Not sure if it''s really a multi-image.  Nice photo though.', '2003-04-28 14:05:16.000000', NULL, 1),
(281023, 19448, 1379, '<td valign="top">What a hilarious composition!  It''s clear that this dog is well loved.  I really like your choice of font and border colors.</td>', 'What a hilarious composition!  It''s clear that this dog is well loved.  I really like your choice of font and border colors.', '2003-04-28 14:06:33.000000', NULL, 1),
(281024, 19685, 3294, '<td valign="top">Great way to illustrate that these are different exposures.  No way both sides could have been moving at the same time.</td>', 'Great way to illustrate that these are different exposures.  No way both sides could have been moving at the same time.', '2003-04-28 14:06:45.000000', NULL, 1),
(281026, 19501, 1379, '<td valign="top">So sweet!  The middle picture is my favorite... That''s the classic, newborn wrinkly expression.  Nice use of sepia.  I hope her/his parents treasure this!</td>', 'So sweet!  The middle picture is my favorite... That''s the classic, newborn wrinkly expression.  Nice use of sepia.  I hope her/his parents treasure this!', '2003-04-28 14:07:42.000000', NULL, 1),
(281027, 19569, 3294, '<td valign="top">Wow!  This composition looks a LOT like mine!  hehe... I like the leaves breaking out of the frame.</td>', 'Wow!  This composition looks a LOT like mine!  hehe... I like the leaves breaking out of the frame.', '2003-04-28 14:08:12.000000', NULL, 1),
(281030, 19579, 1280, '<td valign="top">Very original and well executed!!!</td>', 'Very original and well executed!!!', '2003-04-28 14:10:05.000000', NULL, 1),
