(282034, 19674, 5044, '<td valign="top">Beer, Beer, Beer, wonderful beer! With that Moose there, I''d say a maritimer...LOL<br/>Nice crisp product shots. I can see this on the wall of many college students.</td>', 'Beer, Beer, Beer, wonderful beer! With that Moose there, I''d say a maritimer...LOLNice crisp product shots. I can see this on the wall of many college students.', '2003-04-29 14:44:39.000000', NULL, 1),
(282036, 19763, 7800, '<td valign="top">This is SO much fun. I love her expressions. You''ve got to get this one framed. Good job!</td>', 'This is SO much fun. I love her expressions. You''ve got to get this one framed. Good job!', '2003-04-29 14:45:11.000000', NULL, 1),
(282088, 19106, 7800, '<td valign="top">Lovely sepia pictures. The middle frame bothers me a bit. It''s a little dark and I had to look closely to figure it out.</td>', 'Lovely sepia pictures. The middle frame bothers me a bit. It''s a little dark and I had to look closely to figure it out.', '2003-04-29 14:58:36.000000', NULL, 1),
(282091, 19681, 7800, '<td valign="top">Awesome and orginal. Nobody approached this challenge like you. Good job!</td>', 'Awesome and orginal. Nobody approached this challenge like you. Good job!', '2003-04-29 14:59:08.000000', NULL, 1),
(282111, 19722, 7800, '<td valign="top">Gorgeous use of depth of field, lovely sharp capture. I''d love to know what that blood red spot is.</td>', 'Gorgeous use of depth of field, lovely sharp capture. I''d love to know what that blood red spot is.', '2003-04-29 15:03:07.000000', NULL, 1),
