(282139, 19250, 7800, '<td valign="top">Oh gosh, what awesome pictuures. The colors are amazing.  I don''t love the way you framed them, but everything else is perfect.</td>', 'Oh gosh, what awesome pictuures. The colors are amazing.  I don''t love the way you framed them, but everything else is perfect.', '2003-04-29 15:07:08.000000', NULL, 1),
(282146, 19221, 5918, '<td valign="top">Good job</td>', 'Good job', '2003-04-29 15:07:57.000000', NULL, 1),
(282148, 19764, 6870, '<td valign="top">These three views each have something new to say. Nice work.</td>', 'These three views each have something new to say. Nice work.', '2003-04-29 15:08:39.000000', NULL, 1),
