(287073, 19553, 6230, '<td valign="top">Pretty but what''s the story?</td>', 'Pretty but what''s the story?', '2003-05-04 13:47:17.000000', NULL, 1),
(287077, 19584, 6230, '<td valign="top">Joyful moments.....nice take.</td>', 'Joyful moments.....nice take.', '2003-05-04 13:51:07.000000', NULL, 1),
(287078, 19765, 6230, '<td valign="top">Make a nice postcard.</td>', 'Make a nice postcard.', '2003-05-04 13:52:15.000000', NULL, 1),
(287080, 19681, 6230, '<td valign="top">Great idea...</td>', 'Great idea...', '2003-05-04 13:53:13.000000', NULL, 1),
(287081, 19752, 6230, '<td valign="top">This peacock looks familiar.....</td>', 'This peacock looks familiar.....', '2003-05-04 13:56:06.000000', NULL, 1),
(287086, 19722, 6230, '<td valign="top">Great macros.....what''s the story?</td>', 'Great macros.....what''s the story?', '2003-05-04 14:05:13.000000', NULL, 1),
(287089, 19397, 6230, '<td valign="top">NIce graphics but what''s the story?</td>', 'NIce graphics but what''s the story?', '2003-05-04 14:16:10.000000', NULL, 1),
(287096, 19768, 554, '<td valign="top">nicely done....even if you are one who does not appreciate complements. <br/></td>', 'nicely done....even if you are one who does not appreciate complements. ', '2003-05-04 14:28:46.000000', NULL, 1),
(287097, 19429, 554, '<td valign="top">my favorite</td>', 'my favorite', '2003-05-04 14:30:18.000000', NULL, 1),
(287100, 19710, 6870, '<td valign="top">The disjointed arms really work well for me here, implying that the length is symbolically larger that her arms alone could. Very  hnice work. Excellent tones and lighting as well. Nice use of desaturation. 10! yes 10! I keep coming back to this shot--It has to be my favorite in this challenge. I just love it. Commend your model for me; she has sold this one for you, though your good work enhances everything she does!</td>', 'The disjointed arms really work well for me here, implying that the length is symbolically larger that her arms alone could. Very  hnice work. Excellent tones and lighting as well. Nice use of desaturation. 10! yes 10! I keep coming back to this shot--It has to be my favorite in this challenge. I just love it. Commend your model for me; she has sold this one for you, though your good work enhances everything she does!', '2003-05-04 14:48:40.000000', NULL, 1),
(287101, 19221, 6870, '<td valign="top">They seem oh so slightly ouf of focus, when exact clarity is needed here, but the B/W works wonderfully, and the images really create a synergy. Very nice tones, too. Lovely image. 10</td>', 'They seem oh so slightly ouf of focus, when exact clarity is needed here, but the B/W works wonderfully, and the images really create a synergy. Very nice tones, too. Lovely image. 10', '2003-05-04 14:49:25.000000', NULL, 1),
(287102, 19636, 6870, '<td valign="top">I love the tone, colors and mood here! Even though your title suggest that theyshould be wet, they look almost too wet. Still, very fine work here!</td>', 'I love the tone, colors and mood here! Even though your title suggest that theyshould be wet, they look almost too wet. Still, very fine work here!', '2003-05-04 14:51:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(287104, 19734, 6870, '<td valign="top">Really great idea. I like how the statues kind of blend in tone-wise to the surroundings. A lower point of view would make them appear to be more "heroic." The hightlights on the statues kind of distract somewhat. Focus and DOF works well for me.</td>', 'Really great idea. I like how the statues kind of blend in tone-wise to the surroundings. A lower point of view would make them appear to be more "heroic." The hightlights on the statues kind of distract somewhat. Focus and DOF works well for me.', '2003-05-04 14:53:45.000000', NULL, 1),
(287109, 19583, 2586, '<td valign="top">This is a great advertisement. Although not a beer drinker, i am originally Dutch, so i appreciate the Heineken (the French text was noted so i believe i know who you are) ! The presentation is nicely seamless and layed out in a logical manner. Love the droplets on the bottle; they help my eye wanting to go back into the picture instead of out. Really well done, 10 Journey</td>', 'This is a great advertisement. Although not a beer drinker, i am originally Dutch, so i appreciate the Heineken (the French text was noted so i believe i know who you are) ! The presentation is nicely seamless and layed out in a logical manner. Love the droplets on the bottle; they help my eye wanting to go back into the picture instead of out. Really well done, 10 Journey', '2003-05-04 15:21:01.000000', NULL, 1),
(287110, 19302, 6912, '<td valign="top">Great lighting and wonderful focus! Superb work and excellent idea!</td>', 'Great lighting and wonderful focus! Superb work and excellent idea!', '2003-05-04 15:21:34.000000', NULL, 1),
(287111, 19723, 6912, '<td valign="top">Amazing work, great idea, love everything about it, one of the first 3 for sure, good luck! 10!</td>', 'Amazing work, great idea, love everything about it, one of the first 3 for sure, good luck! 10!', '2003-05-04 15:23:25.000000', NULL, 1),
(287112, 19579, 6912, '<td valign="top">Roll roll roll, you are on roll! Wow! That must have been a hell of a long time to make a masterpiece like that! 10!</td>', 'Roll roll roll, you are on roll! Wow! That must have been a hell of a long time to make a masterpiece like that! 10!', '2003-05-04 15:25:13.000000', NULL, 1),
(287113, 19358, 6912, '<td valign="top">Touching and sweet, my 3rd and the last 10 in this challenge! Good luck!</td>', 'Touching and sweet, my 3rd and the last 10 in this challenge! Good luck!', '2003-05-04 15:25:57.000000', NULL, 1),
(287114, 19759, 2586, '<td valign="top">Fun image, nice layout, nice variety of images on the same, very limited, theme (didn''t care for those submissions where one of the images was a repeat). Love the warm skin tones. Just the other day i saw a fun image by kkreeper and wonder whether this is him again? :) You''ve got your eye on me? Am tired of you staring at me, why don''t you take a picture - lasts longer ;) 8 Journey</td>', 'Fun image, nice layout, nice variety of images on the same, very limited, theme (didn''t care for those submissions where one of the images was a repeat). Love the warm skin tones. Just the other day i saw a fun image by kkreeper and wonder whether this is him again? :) You''ve got your eye on me? Am tired of you staring at me, why don''t you take a picture - lasts longer ;) 8 Journey', '2003-05-04 15:26:25.000000', NULL, 1),
(287117, 19717, 4493, '<td valign="top">Your capture of emotion is excellent. Each frame stands well on its own, but coupled together with the others, makes for an excellent composition. I do however,  feel that the lower frame is just a little to dark. Very nicely done.</td>', 'Your capture of emotion is excellent. Each frame stands well on its own, but coupled together with the others, makes for an excellent composition. I do however,  feel that the lower frame is just a little to dark. Very nicely done.', '2003-05-04 15:41:17.000000', NULL, 1),
(287118, 19759, 4493, '<td valign="top">I don''t usually score eyeball shots high, but this is an exception. The focus and clarity captured is well done. Your skin tones are soft and smooth. The top left eyeball may be looking a little to far to the left, but overall this is a nicely laid out triptych.</td>', 'I don''t usually score eyeball shots high, but this is an exception. The focus and clarity captured is well done. Your skin tones are soft and smooth. The top left eyeball may be looking a little to far to the left, but overall this is a nicely laid out triptych.', '2003-05-04 15:43:13.000000', NULL, 1),
(287120, 19727, 4493, '<td valign="top">Where''s my mit? This is a very classic shot. It is unfortunate that we were limited to 640 on this challenge as I think that this would look very nice scaled larger. I gave this a higher than average score as I feel you have presented this nicely and the individual shots put together have a very strong theme.</td>', 'Where''s my mit? This is a very classic shot. It is unfortunate that we were limited to 640 on this challenge as I think that this would look very nice scaled larger. I gave this a higher than average score as I feel you have presented this nicely and the individual shots put together have a very strong theme.', '2003-05-04 15:45:21.000000', NULL, 1),
(287122, 19712, 4493, '<td valign="top">Nice postprocessing. I like the feel given to your structure. The greens and browns work well together.</td>', 'Nice postprocessing. I like the feel given to your structure. The greens and browns work well together.', '2003-05-04 15:46:18.000000', NULL, 1),
(287123, 19628, 4493, '<td valign="top">Very good captures of 3 fine cars. The colors and layout work very well and convey a very professional print format. This is nicely done and has placed high on my list.</td>', 'Very good captures of 3 fine cars. The colors and layout work very well and convey a very professional print format. This is nicely done and has placed high on my list.', '2003-05-04 15:47:40.000000', NULL, 1),
(287133, 19448, 5391, '<td valign="top">Absolutely brilliant photos.  Each one is perfect in and of itself, and together they tell a great story.  I like your use of creative camera angle, and the dog is a brilliant actor.  Made me laugh out loud.  One of my favorites so far.  10</td>', 'Absolutely brilliant photos.  Each one is perfect in and of itself, and together they tell a great story.  I like your use of creative camera angle, and the dog is a brilliant actor.  Made me laugh out loud.  One of my favorites so far.  10', '2003-05-04 16:39:59.000000', NULL, 1),
(287134, 19234, 5391, '<td valign="top">Very nice framing and good idea for the challenge.   Whenever photographing eyes, I always try and get a "catch light" - a tiny spot of light reflected in the eye.  It helps make the eye look really alive and pop out at you.  I think that would make this a 10.  But very nice as it is.</td>', 'Very nice framing and good idea for the challenge.   Whenever photographing eyes, I always try and get a "catch light" - a tiny spot of light reflected in the eye.  It helps make the eye look really alive and pop out at you.  I think that would make this a 10.  But very nice as it is.', '2003-05-04 16:44:26.000000', NULL, 1),
(287137, 19725, 5391, '<td valign="top">Frank would have been pleased with this.  I think perhaps the image on the right is disturbed with the shadows from the tree, however, considering FLW''s designs that blended structure and the natural landscape into one, in a way, it goes along with his design...  Nice work.  9</td>', 'Frank would have been pleased with this.  I think perhaps the image on the right is disturbed with the shadows from the tree, however, considering FLW''s designs that blended structure and the natural landscape into one, in a way, it goes along with his design...  Nice work.  9', '2003-05-04 16:51:37.000000', NULL, 1),
(287139, 19569, 5391, '<td valign="top">Creative.  I can see this as a poster in an import store.  My only nit pick would be the tiny blown out highlights that are minorly distracting.  But overall very nice.  8</td>', 'Creative.  I can see this as a poster in an import store.  My only nit pick would be the tiny blown out highlights that are minorly distracting.  But overall very nice.  8', '2003-05-04 16:55:53.000000', NULL, 1),
(287140, 19757, 5391, '<td valign="top">One of the more clever ideas of this challenge.  I like that you''ve captured different times and placed them all together as if one photograph.</td>', 'One of the more clever ideas of this challenge.  I like that you''ve captured different times and placed them all together as if one photograph.', '2003-05-04 16:58:28.000000', NULL, 1),
(287145, 19415, 5391, '<td valign="top">Beautiful.  Each image stands well on its own.  The high-contrast silhouettes work very well.  9</td>', 'Beautiful.  Each image stands well on its own.  The high-contrast silhouettes work very well.  9', '2003-05-04 17:00:09.000000', NULL, 1),
(287154, 19750, 2110, '<td valign="top">very nice chice of images.. i just feel that your stark black borders do not do justice to the softness inthe images. Also perhaps if the gaps between the three images is a little less, it may reduce the geometric effect of the of the overall composition and allw the viewer to enjoy the images more...Good luck !!</td>', 'very nice chice of images.. i just feel that your stark black borders do not do justice to the softness inthe images. Also perhaps if the gaps between the three images is a little less, it may reduce the geometric effect of the of the overall composition and allw the viewer to enjoy the images more...Good luck !!', '2003-05-04 17:24:22.000000', NULL, 1),
(287155, 19737, 2110, '<td valign="top">I guess the uneven distance from the edges of the white ellipses ( in the side images ) is a little disturbing in a symmetric composition like this. Also i fell if the central image had the two of them in a close up (closer that the side images -may be just the intreference of the hands), it can work better.</td>', 'I guess the uneven distance from the edges of the white ellipses ( in the side images ) is a little disturbing in a symmetric composition like this. Also i fell if the central image had the two of them in a close up (closer that the side images -may be just the intreference of the hands), it can work better.', '2003-05-04 17:28:44.000000', NULL, 1),
(287156, 19587, 2110, '<td valign="top">I like the idea, it makes you thnk...I guess the distance on the sides of the central image is a little too much. Also since there is a lot of black in the central image (near the top edge), that frame looks smaller than the other two and that is a little disturbing. Image one is very interesting, image two builds up, but image three is kind of an anti climax- well if you are from some Arabic country where people read from left to right, this is a great sequence!!</td>', 'I like the idea, it makes you thnk...I guess the distance on the sides of the central image is a little too much. Also since there is a lot of black in the central image (near the top edge), that frame looks smaller than the other two and that is a little disturbing. Image one is very interesting, image two builds up, but image three is kind of an anti climax- well if you are from some Arabic country where people read from left to right, this is a great sequence!!', '2003-05-04 17:34:28.000000', NULL, 1),
(287157, 19763, 2110, '<td valign="top">Action really build up in this composition- perhaps swapping 2nd and 3rd would have been a better climax.  Perhaps not..you chose to end the cycle!<br/>I like this image..it has a lot of life in it..</td>', 'Action really build up in this composition- perhaps swapping 2nd and 3rd would have been a better climax.  Perhaps not..you chose to end the cycle!I like this image..it has a lot of life in it..', '2003-05-04 17:38:18.000000', NULL, 1),
(287158, 19625, 2110, '<td valign="top">I guess such images make a great impact when they are absolutely perfect! A good try indeed..</td>', 'I guess such images make a great impact when they are absolutely perfect! A good try indeed..', '2003-05-04 17:39:37.000000', NULL, 1),
(287160, 19727, 2110, '<td valign="top">I love the way the shadow comes into the scene!! very dynamic and very nicely done.. though a simple idea.</td>', 'I love the way the shadow comes into the scene!! very dynamic and very nicely done.. though a simple idea.', '2003-05-04 17:41:47.000000', NULL, 1),
(287162, 19757, 2110, '<td valign="top">I love the idea..it would have a greater impact if the foreground in the third image also had a little different color treatment to it...</td>', 'I love the idea..it would have a greater impact if the foreground in the third image also had a little different color treatment to it...', '2003-05-04 17:44:19.000000', NULL, 1),
(287164, 19710, 2110, '<td valign="top">What if the text also stretched a little more??</td>', 'What if the text also stretched a little more??', '2003-05-04 17:46:29.000000', NULL, 1),
(287166, 19514, 2110, '<td valign="top">I guess you need some more vitamins in your diet!!<br/>Nice colors.. if the central image was  a little more zoomed in and was croped a little at the bottom edge, I feel it could have made a better composition.</td>', 'I guess you need some more vitamins in your diet!!Nice colors.. if the central image was  a little more zoomed in and was croped a little at the bottom edge, I feel it could have made a better composition.', '2003-05-04 17:49:02.000000', NULL, 1),
(287168, 19636, 2110, '<td valign="top">image one and two make a great composition together!! Was the third one really required??</td>', 'image one and two make a great composition together!! Was the third one really required??', '2003-05-04 17:52:55.000000', NULL, 1),
(287172, 19579, 2110, '<td valign="top">These ones look harmless!!<br/>I like the way you have created interest in the composition by the third face looking into the frame. Perhaps face one could also have been a little different to create more interest...<br/></td>', 'These ones look harmless!!I like the way you have created interest in the composition by the third face looking into the frame. Perhaps face one could also have been a little different to create more interest...', '2003-05-04 18:05:57.000000', NULL, 1),
(287175, 19415, 772, '<td valign="top">very hice work... i particularly like the center image... the boat through the trees is great :) - setzler</td>', 'very hice work... i particularly like the center image... the boat through the trees is great :) - setzler', '2003-05-04 18:15:51.000000', NULL, 1),
(287176, 19760, 772, '<td valign="top">excellent composition... black and white was a good choice... the perspective on the cross is also excellent... the celtic knots detail shows nicely :) - setzler</td>', 'excellent composition... black and white was a good choice... the perspective on the cross is also excellent... the celtic knots detail shows nicely :) - setzler', '2003-05-04 18:16:52.000000', NULL, 1),
(287177, 19628, 772, '<td valign="top">beautiful perspectives on these cars... the lighting is phenomenal... great work :) - setzler</td>', 'beautiful perspectives on these cars... the lighting is phenomenal... great work :) - setzler', '2003-05-04 18:17:25.000000', NULL, 1),
(287178, 19636, 772, '<td valign="top">these are excellent macro shots... i think the composition would be even stronger if there was some more separation between each image...</td>', 'these are excellent macro shots... i think the composition would be even stronger if there was some more separation between each image...', '2003-05-04 18:18:32.000000', NULL, 1),
(287179, 19761, 772, '<td valign="top">excellent work with the lighting... the theme is also very strong :)</td>', 'excellent work with the lighting... the theme is also very strong :)', '2003-05-04 18:19:00.000000', NULL, 1),
(287181, 19727, 772, '<td valign="top">This is a nice composition and storyline... i think it would be even stronger if you had horizontally flipped each image where the action was going to the right rather than the left...</td>', 'This is a nice composition and storyline... i think it would be even stronger if you had horizontally flipped each image where the action was going to the right rather than the left...', '2003-05-04 18:20:19.000000', NULL, 1),
(287183, 19541, 772, '<td valign="top">interesting concept :)  I think you could probably use some visible separation between each image to make the triptych theme even stronger...</td>', 'interesting concept :)  I think you could probably use some visible separation between each image to make the triptych theme even stronger...', '2003-05-04 18:21:18.000000', NULL, 1),
(287186, 19360, 772, '<td valign="top">excellent portrait series... i think some stronger division between the images would be good also... the 2 and 3 image are blending together and the separation is not as strong as between 1 and 2...</td>', 'excellent portrait series... i think some stronger division between the images would be good also... the 2 and 3 image are blending together and the separation is not as strong as between 1 and 2...', '2003-05-04 18:23:52.000000', NULL, 1),
(287187, 19553, 772, '<td valign="top">excellent work with the red... the lighting on these tulips is perfect :)</td>', 'excellent work with the red... the lighting on these tulips is perfect :)', '2003-05-04 18:24:50.000000', NULL, 1),
(287188, 19613, 772, '<td valign="top">excellent theme for a triptych :)  I think the background color should be more representative somehow...</td>', 'excellent theme for a triptych :)  I think the background color should be more representative somehow...', '2003-05-04 18:25:35.000000', NULL, 1),
(287189, 19406, 772, '<td valign="top">interesting images... the background color is not creating great separation.... the flow from top to bottom is a bit awkward as well...</td>', 'interesting images... the background color is not creating great separation.... the flow from top to bottom is a bit awkward as well...', '2003-05-04 18:26:48.000000', NULL, 1),
(287190, 19674, 772, '<td valign="top">good work with the white background, but the bottles look like they are floating in space...</td>', 'good work with the white background, but the bottles look like they are floating in space...', '2003-05-04 18:27:26.000000', NULL, 1),
(287191, 19749, 2110, '<td valign="top">A littel more black space on the top would have helped!<br/>Zoom out image one a littel bit, that may bring in more harmony as the amount of white has increased in image three.<br/>It makes me think! I like it..</td>', 'A littel more black space on the top would have helped!Zoom out image one a littel bit, that may bring in more harmony as the amount of white has increased in image three.It makes me think! I like it..', '2003-05-04 18:27:28.000000', NULL, 1),
(287193, 19759, 772, '<td valign="top">excellent theme... good work with the macro shots also... :)</td>', 'excellent theme... good work with the macro shots also... :)', '2003-05-04 18:28:33.000000', NULL, 1),
(287194, 19280, 772, '<td valign="top">excellent toning in these photos... something is a bit goofy in the top center background of the image though....</td>', 'excellent toning in these photos... something is a bit goofy in the top center background of the image though....', '2003-05-04 18:29:54.000000', NULL, 1),
(287195, 19584, 772, '<td valign="top">excellent series... congrats on the new birth :)</td>', 'excellent series... congrats on the new birth :)', '2003-05-04 18:30:39.000000', NULL, 1),
(287206, 19628, 3320, '<td valign="top">Good idea and realisation except the whie floor for the bottom car. It braks the unitu I think</td>', 'Good idea and realisation except the whie floor for the bottom car. It braks the unitu I think', '2003-05-04 18:54:04.000000', NULL, 1),
(287212, 19710, 4007, '<td valign="top">I like the creative idea with the arms cut out.  I''m not sure why you desaturated everything but red though, as the color doesn''t have any significant function here.  Also, the facial expression doesn''t do much for me.  Good luck. 5</td>', 'I like the creative idea with the arms cut out.  I''m not sure why you desaturated everything but red though, as the color doesn''t have any significant function here.  Also, the facial expression doesn''t do much for me.  Good luck. 5', '2003-05-04 19:21:35.000000', NULL, 1),
(287213, 19576, 7350, '<td valign="top">Gun, Cuffs, and......pens?  The pens don''t seem to fit, though I''m sure you use them a lot.  Nightstick maybe, or siren lights?</td>', 'Gun, Cuffs, and......pens?  The pens don''t seem to fit, though I''m sure you use them a lot.  Nightstick maybe, or siren lights?', '2003-05-04 19:22:08.000000', NULL, 1),
(287215, 19719, 4007, '<td valign="top">This is a very cool idea, and it''s executed well.The different colors are very effective.  I like how the images are progressive, but also overlap a bit.  Nice work. 8</td>', 'This is a very cool idea, and it''s executed well.The different colors are very effective.  I like how the images are progressive, but also overlap a bit.  Nice work. 8', '2003-05-04 19:23:33.000000', NULL, 1),
(287217, 19688, 4007, '<td valign="top">A great concept, and a beautiful study in patterns of black and white.  I think this shot would be helped greatly if all three frames were more crisp, as the salt/pepper shakers all seem to have too much blur to them.  Nice work. 8</td>', 'A great concept, and a beautiful study in patterns of black and white.  I think this shot would be helped greatly if all three frames were more crisp, as the salt/pepper shakers all seem to have too much blur to them.  Nice work. 8', '2003-05-04 19:26:42.000000', NULL, 1),
(287219, 19406, 4007, '<td valign="top">The bottom two shots come across as cluttered.</td>', 'The bottom two shots come across as cluttered.', '2003-05-04 19:31:52.000000', NULL, 1),
(287220, 19358, 4007, '<td valign="top">There''s some interesting photoshop work here, but this still isn''t a multi-image composition, it''s just one image with some frames laid over it.  However, I do like how each of the frames represents a different crop of the shot, each of which would be very effective (especially the top two).  It''s a good shot, but only by the farthest stretch of imagination does this fit the challenge. 4<br/><br/><i>Message edited by author 2003-05-05 09:00:25.</i></td>', 'There''s some interesting photoshop work here, but this still isn''t a multi-image composition, it''s just one image with some frames laid over it.  However, I do like how each of the frames represents a different crop of the shot, each of which would be very effective (especially the top two).  It''s a good shot, but only by the farthest stretch of imagination does this fit the challenge. 4', '2003-05-04 19:34:18.000000', '2003-05-05 10:00:25.000000', 1),
(287223, 19749, 4007, '<td valign="top">I''m really not sure why there''s all that black space at the bottom, but a tighter frame would definately help here.  I like the middle shot, because the captured expression seems the most authentic, and it seems to be the most genuine representation of the person (who I''m guessing is you).  Maybe instead of different expressions this could have been done with different zooms or angles instead.  I do like the extreme contrast effect, and how you worked the background into it.  The abstract result works well. 7 (mostly for the center frame)</td>', 'I''m really not sure why there''s all that black space at the bottom, but a tighter frame would definately help here.  I like the middle shot, because the captured expression seems the most authentic, and it seems to be the most genuine representation of the person (who I''m guessing is you).  Maybe instead of different expressions this could have been done with different zooms or angles instead.  I do like the extreme contrast effect, and how you worked the background into it.  The abstract result works well. 7 (mostly for the center frame)', '2003-05-04 19:40:05.000000', NULL, 1),
(287228, 19355, 806, '<td valign="top">this is nice. very much tells a story .. expecially the hand in the soil makes it feel like a labo of love.</td>', 'this is nice. very much tells a story .. expecially the hand in the soil makes it feel like a labo of love.', '2003-05-04 20:30:25.000000', NULL, 1),
(287229, 19569, 806, '<td valign="top">I like how you made the leaves go outside the border. very nice multi-image. worthy of print.</td>', 'I like how you made the leaves go outside the border. very nice multi-image. worthy of print.', '2003-05-04 20:31:16.000000', NULL, 1),
(287232, 19069, 806, '<td valign="top">I''d like a bit more light on the fan in the center panel. otherwise a nice display.</td>', 'I''d like a bit more light on the fan in the center panel. otherwise a nice display.', '2003-05-04 20:36:16.000000', NULL, 1),
